import re, glob, collections
html_classes=collections.Counter()
for f in glob.glob('site/*.html'):
    s=open(f).read()
    for m in re.finditer(r'class="([^"]+)"', s):
        for c in m.group(1).split(): html_classes[c]+=1
css=open('site/css/base.css').read()+open('site/css/components.css').read()+open('site/css/pages.css').read()+open('site/css/tokens.css').read()
css_classes=set(re.findall(r'\.([a-zA-Z][\w-]*)', css))
print("HTML classes not in CSS:")
for c,n in sorted(html_classes.items()):
    if c not in css_classes: print(f"  {c} ({n})")
print("\nCSS classes not used in HTML:")
for c in sorted(css_classes):
    if c not in html_classes: print(f"  {c}")
EOF

