cat > "$TMPDIR/cssrules.mjs" <<'EOF'
import { chromium } from '/tmp/avb-Y0eNcU/project/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto('http://127.0.0.1:4173/index.html', {waitUntil:'networkidle'});
const out = await page.evaluate(() => {
  const problems=[];
  const walk=(rules, sheet)=>{
    for (const r of rules){
      if (r.type===1){
        const n = r.style.length;
        // count semicolons at top level in style.cssText
        let depth=0, count=0;
        for (const ch of r.style.cssText){ if(ch==='(')depth++; else if(ch===')')depth--; else if(ch===';'&&depth===0)count++; }
        if (n!==count) problems.push({sheet:sheet, selector:r.selectorText, declared:count, parsed:n, css:r.style.cssText});
        for (let i=0;i<n;i++){ const p=r.style[i]; const v=r.style.getPropertyValue(p); if(!v.trim()) problems.push({sheet,selector:r.selectorText,empty:p}); }
      } else if (r.cssRules) walk(r.cssRules, sheet);
    }
  };
  for (const s of document.styleSheets){
    try { walk(s.cssRules, s.href); } catch(e){ problems.push({sheet:s.href, error:String(e)}); }
  }
  const sheets=[...document.styleSheets].map(s=>({href:s.href, rules:s.cssRules.length}));
  return {sheets, problems};
});
console.log(JSON.stringify(out,null,1));
await browser.close();
EOF
