cat > "$TMPDIR/csssupports.mjs" <<'EOF'
import { chromium } from '/tmp/avb-Y0eNcU/project/node_modules/playwright/index.mjs';
const files=['tokens','base','components','pages'];
const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto('http://127.0.0.1:4173/index.html');
const results = await page.evaluate(async (files) => {
  const bad=[];
  for (const f of files){
    const text=await (await fetch(`/css/${f}.css`)).text();
    // tokenise simply: walk chars, track blocks; parse declarations at depth 1 in style blocks
    let i=0, depth=0, buf='', selector='', inAtRule=null;
    const decls=[];
    let stack=[];
    let currentSel='';
    let j=0;
    // use a basic state machine
    let blocks=[]; // {prelude, body}
    let start=0;
    // strip comments
    const s=text.replace(/\/\*[\s\S]*?\*\//g,'');
    const parseBlocks=(str)=>{
      let out=[]; let d=0; let seg=''; let prelude=''; let inBlockBody='';
      for (let k=0;k<str.length;k++){
        const ch=str[k];
        if (ch==='{'){ d++; if(d===1){prelude=seg.trim();seg='';} else seg+=ch; }
        else if (ch==='}'){ d--; if(d===0){out.push({prelude, body:seg}); seg='';} else seg+=ch; }
        else if (ch===';' && d===0){ prelude=seg.trim(); seg=''; }
        else seg+=ch;
      }
      return out;
    };
    const top=parseBlocks(s);
    const visit=(blocks, inAt=false)=>{
      for (const b of blocks){
        if (b.prelude.startsWith('@')){
          if (b.prelude.startsWith('@media') || b.prelude.startsWith('@supports')){
            visit(parseBlocks(b.body), true);
          }
          continue;
        }
        if (b.prelude.startsWith('@font-face')) continue;
        for (const part of b.body.split(';')){
          const idx=part.indexOf(':');
          if(idx<0) continue;
          const prop=part.slice(0,idx).trim();
          const val=part.slice(idx+1).trim();
          if(!prop||!val) continue;
          if(prop.startsWith('--')) continue;
          if(!CSS.supports(prop,val)) bad.push({file:f, selector:b.prelude, prop, val});
        }
      }
    };
    visit(top);
  }
  return bad;
}, files);
console.log(JSON.stringify(results,null,1));
await browser.close();
EOF
