python3 - <<'EOF'
import re,glob,collections
sel=collections.defaultdict(list)
for f in ['site/css/tokens.css','site/css/base.css','site/css/components.css','site/css/pages.css']:
    s=open(f).read()
    s=re.sub(r'/\*.*?\*/','',s,flags=re.S)
    # remove @media wrappers crudely by parsing braces
    def parse(text, prefix=''):
        i=0; buf=''; selbuf=''
        while i<len(text):
            c=text[i]
            if c=='{':
                # find matching
                depth=1; j=i+1; body=''
                while j<len(text) and depth:
                    if text[j]=='{': depth+=1
                    elif text[j]=='}': depth-=1
                    if depth: body+=text[j]
                    j+=1
                if selbuf.strip().startswith('@media'):
                    parse(body, selbuf.strip()+' ')
                else:
                    sel[prefix+selbuf.strip()].append((f,body))
                selbuf=''
                i=j
            elif c=='}':
                i+=1
            else:
                selbuf+=c; i+=1
    parse(s)
for k,v in sel.items():
    if len(v)>1 and not k.startswith('@'):
        print(k, [f for f,b in v])
EOF

